import { DecimalColumn, DocumentIdColumn, ReferenceColumn, StringColumn, Table } from '../../db'

export const sys_variable_value = Table({
    name: 'sys_variable_value',
    extends: 'sys_metadata',
    schema: {
        document: StringColumn({}),
        value: StringColumn({}),
        variable: ReferenceColumn({ referenceTable: 'var_dictionary' }),
        order: DecimalColumn({}),
        document_key: DocumentIdColumn({ dependent: 'document' }),
    },
})
